"""The certified fact corpus, generated — do not edit by hand.

Every entry is a quantity this lab has enclosed in exact arithmetic, with the
record it came from and that record's sha256 beside it. Endpoints are exact
rationals (numerator, denominator): a certificate is a proof about an interval,
and storing it as a decimal would throw away the thing this environment exists
to talk about.

Generated by tools/build-gym-facts.js from the cert-machine records.
"""
from fractions import Fraction
from typing import NamedTuple, Optional


class Fact(NamedTuple):
    id: str
    what: str
    tier: str
    lo: Fraction
    hi: Fraction
    record: Optional[str]
    sha256: Optional[str]
    published_wrong: Optional[float]

    @property
    def width(self) -> Fraction:
        return self.hi - self.lo

    @property
    def midpoint(self) -> Fraction:
        return (self.lo + self.hi) / 2


